<?php
require __DIR__.'/config.php';$me=require_staff();$pdo=db();$scopeA=branch_scope('a');$scopeC=branch_scope('c');$customerScope=$me['role']==='Administrator'?'':' AND c.branch_id='.(int)$me['branch_id'];
$stats=[];$stats['customers']=(int)$pdo->query("SELECT COUNT(*) FROM customers c WHERE 1=1 $scopeC")->fetchColumn();$stats['accounts']=(int)$pdo->query("SELECT COUNT(*) FROM accounts a WHERE a.status='active' $scopeA")->fetchColumn();$stats['balance']=(float)$pdo->query("SELECT COALESCE(SUM(a.balance),0) FROM accounts a WHERE a.status='active' $scopeA")->fetchColumn();$stats['loans']=(int)$pdo->query("SELECT COUNT(DISTINCT l.loan_id) FROM loans l JOIN loan_parties lp ON lp.loan_id=l.loan_id AND lp.party_role='borrower' JOIN customers c ON c.customer_id=lp.customer_id WHERE l.status IN ('approved','active') $customerScope")->fetchColumn();$stats['pending']=(int)$pdo->query("SELECT (SELECT COUNT(*) FROM accounts a WHERE a.status='pending' $scopeA)+(SELECT COUNT(*) FROM customers c WHERE c.kyc_status='pending' $scopeC)")->fetchColumn();
$today=$pdo->query("SELECT COUNT(*) AS n,COALESCE(SUM(CASE WHEN t.transaction_type IN ('deposit','transfer_in','interest') THEN t.amount ELSE 0 END),0) AS incoming,COALESCE(SUM(CASE WHEN t.transaction_type IN ('withdrawal','transfer_out','fee') THEN t.amount ELSE 0 END),0) AS outgoing FROM transactions t JOIN accounts a ON a.account_id=t.account_id WHERE t.status='completed' AND DATE(t.created_at)=CURDATE() $scopeA")->fetch();
$recent=$pdo->query("SELECT t.transaction_id,t.reference_number,t.transaction_type,t.amount,t.created_at,a.account_number FROM transactions t JOIN accounts a ON a.account_id=t.account_id WHERE 1=1 $scopeA ORDER BY t.created_at DESC LIMIT 8")->fetchAll();$branchRows=$me['role']==='Administrator'?$pdo->query("SELECT b.branch_name,COUNT(DISTINCT a.account_id) AS accounts,COALESCE(SUM(a.balance),0) AS balance FROM branches b LEFT JOIN accounts a ON a.branch_id=b.branch_id GROUP BY b.branch_id ORDER BY b.branch_name")->fetchAll():[];
page_start('Dashboard');?>
<div class="pagehead"><div><div class="eyebrow"><?=e($me['role'])?> workspace</div><h1>Dashboard</h1><span class="muted">Welcome, <?=e($me['name'])?> · <?=$me['role']==='Administrator'?'All branches':'Your assigned branch'?></span></div><a class="button yellow" href="<?=e(url('module.php?view=transactions'))?>">Process transaction</a></div>
<div class="cards"><?php foreach([['Customers',$stats['customers']],['Active accounts',$stats['accounts']],['Active balances','BDT '.number_format($stats['balance'],2)],['Loans in progress',$stats['loans']],['Pending tasks',$stats['pending']],['Today transactions',(int)$today['n']],['Today deposits','BDT '.number_format((float)$today['incoming'],2)],['Today withdrawals','BDT '.number_format((float)$today['outgoing'],2)]] as [$label,$value]):?><div class="stat"><label><?=e($label)?></label><strong><?=e($value)?></strong></div><?php endforeach;?></div>
<div class="panel"><h2>Quick actions</h2><div class="filters"><a class="button yellow" href="<?=e(url('module.php?view=customers'))?>">Review KYC</a><a class="button blue" href="<?=e(url('module.php?view=accounts'))?>">Approve accounts</a><a class="button" href="<?=e(url('module.php?view=loans'))?>">Review loans</a><a class="button" href="<?=e(url('module.php?view=reports'))?>">Reports</a></div></div>
<div class="panel"><h2>Recent transactions</h2><div class="table-scroll"><table><thead><tr><th>Date</th><th>Reference</th><th>Account</th><th>Type</th><th>Amount</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['reference_number'])?></td><td><?=e($r['account_number'])?></td><td><?=e(ucwords(str_replace('_',' ',$r['transaction_type'])))?></td><td>BDT <?=number_format((float)$r['amount'],2)?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php if($branchRows):?><div class="panel"><h2>Branch summary</h2><div class="table-scroll"><table><thead><tr><th>Branch</th><th>Accounts</th><th>Balance</th></tr></thead><tbody><?php foreach($branchRows as $b):?><tr><td><?=e($b['branch_name'])?></td><td><?=e($b['accounts'])?></td><td>BDT <?=number_format((float)$b['balance'],2)?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;?><?php page_end();
